using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Markup;
using Microsoft.UI.Xaml.Media;
using System.Text.Json;
namespace NavigationControlsProbe;
public sealed partial class ProbeApplication {
 object Value(object o,string key)=>o.GetType().GetProperty(key)?.GetValue(o)?.ToString()??"missing";
 async Task CommandControls(){
  window.AppWindow.ResizeClient(new Windows.Graphics.SizeInt32((int)Math.Ceiling(800*root.XamlRoot.RasterizationScale),(int)Math.Ceiling(450*root.XamlRoot.RasterizationScale)));await Task.Delay(250);
  var spec=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"command-controls-template.json"))).RootElement;var palettes=new Dictionary<string,object>();var rows=new List<object>();var missing=new List<object>();
  async Task Record(string theme,string kind,string name,Control control,object props,string state="Normal"){
   root.Children.Clear();var canvas=new Canvas();root.Children.Add(canvas);canvas.Children.Add(control);Canvas.SetLeft(control,24);Canvas.SetTop(control,24);root.UpdateLayout();await Task.Delay(650);
   if(control is CommandBar command){var requested=(bool)props.GetType().GetProperty("isOpen")!.GetValue(props)!;command.IsOpen=requested;root.UpdateLayout();await Task.Delay(400);}
   Control stateTarget=control;if(kind=="SelectorBar")stateTarget=((SelectorBar)control).Items[0];var applied=VisualStateManager.GoToState(stateTarget,kind=="SelectorBar"&&state=="PointerOver"?"UnselectedPointerOver":state,false);root.UpdateLayout();await Task.Delay(100);
   var id=$"{theme}-{kind}-{name}";await Image(id);await OwnCompositorImage(id);File.Copy(Path.Combine(Program.Output,id+"-compositor.png"),Path.Combine(Program.Output,id+"-window.png"),true);rows.Add(new{id,theme,kind,props,state,applied,rect=Rect(control),desired=new[]{control.DesiredSize.Width,control.DesiredSize.Height},defaults=new{minWidth=control.MinWidth,minHeight=control.MinHeight,font=control.FontFamily.Source,fontSize=control.FontSize,padding=Thickness(control.Padding),cornerRadius=new[]{control.CornerRadius.TopLeft,control.CornerRadius.TopRight,control.CornerRadius.BottomRight,control.CornerRadius.BottomLeft},labelPosition=Value(control,"LabelPosition"),closedDisplayMode=Value(control,"ClosedDisplayMode"),isCompact=Value(control,"IsCompact"),isOpen=Value(control,"IsOpen")},parts=Tree(control).OfType<FrameworkElement>().Select(Part).ToArray(),popups=VisualTreeHelper.GetOpenPopupsForXamlRoot(root.XamlRoot).Select(p=>p.Child).OfType<FrameworkElement>().Select(p=>new{type=p.GetType().Name,rect=Rect(p),parts=Tree(p).OfType<FrameworkElement>().Select(Part).ToArray()}).ToArray()});
  }
  foreach(var theme in new[]{"Light","Dark"}){
   root.RequestedTheme=Enum.Parse<ElementTheme>(theme);root.Background=Solid(theme=="Light"?"F3F3F3":"202020");var palette=new Dictionary<string,object>();
   foreach(var key in spec.GetProperty("brushes").EnumerateArray().Select(v=>v.GetString()!))try{var swatch=(Border)XamlReader.Load($"<Border xmlns=\"http://schemas.microsoft.com/winfx/2006/xaml/presentation\" Background=\"{{ThemeResource {key}}}\"/>");root.Children.Add(swatch);root.UpdateLayout();var value=Brush(swatch.Background);if(value!=null)palette[key]=value;else missing.Add(new{theme,key});root.Children.Remove(swatch);}catch(Exception e){missing.Add(new{theme,key,error=e.Message});}palettes[theme]=palette;
   foreach(var state in new[]{"Normal","PointerOver","Pressed","Disabled"})await Record(theme,"AppBarButton",state,new AppBarButton{Label="SymbolIcon",Icon=new SymbolIcon(Symbol.Like),IsEnabled=state!="Disabled"},new{label="SymbolIcon",icon="Like",enabled=state!="Disabled"},state);
   await Record(theme,"AppBarButton","Compact",new AppBarButton{Label="SymbolIcon",Icon=new SymbolIcon(Symbol.Like),IsCompact=true},new{label="SymbolIcon",icon="Like",isCompact=true});
   foreach(var check in new[]{false,true})foreach(var state in new[]{"Normal","PointerOver","Pressed"})await Record(theme,"AppBarToggleButton",$"{check}-{state}",new AppBarToggleButton{Label="SymbolIcon",Icon=new SymbolIcon(Symbol.Shuffle),IsChecked=check},new{label="SymbolIcon",icon="Shuffle",isChecked=check},check?state=="Normal"?"Checked":"Checked"+state:state);
   await Record(theme,"AppBarToggleButton","Mixed",new AppBarToggleButton{Label="PathIcon",IsThreeState=true,IsChecked=null,Icon=new SymbolIcon(Symbol.Shuffle)},new{label="PathIcon",icon="Shuffle",isChecked=(bool?)null,isThreeState=true},"Indeterminate");
   await Record(theme,"AppBarToggleButton","Disabled",new AppBarToggleButton{Label="SymbolIcon",Icon=new SymbolIcon(Symbol.Shuffle),IsChecked=true,IsEnabled=false},new{label="SymbolIcon",icon="Shuffle",isChecked=true,enabled=false},"CheckedDisabled");
   foreach(var state in new[]{"Normal","PointerOver","Pressed","Disabled"})await Record(theme,"DropDownButton",state,new DropDownButton{Content="Email",IsEnabled=state!="Disabled"},new{text="Email",enabled=state!="Disabled"},state);
   foreach(var selected in new[]{-1,0,1}){var bar=new SelectorBar();var labels=new[]{"Recent","Shared","Favorites"};var icons=new[]{Symbol.Clock,Symbol.Share,Symbol.Favorite};for(int i=0;i<3;i++)bar.Items.Add(new SelectorBarItem{Text=labels[i],Icon=new SymbolIcon(icons[i]),IsSelected=i==selected});await Record(theme,"SelectorBar",$"Selection-{selected}",bar,new{selectedIndex=selected});}
   foreach(var state in new[]{"PointerOver","Disabled"}){var bar=new SelectorBar();bar.Items.Add(new SelectorBarItem{Text="Recent",Icon=new SymbolIcon(Symbol.Clock),IsEnabled=state!="Disabled"});bar.Items.Add(new SelectorBarItem{Text="Shared",Icon=new SymbolIcon(Symbol.Share)});await Record(theme,"SelectorBar",state,bar,new{disabledFirst=state=="Disabled"},state);}
   foreach(var conf in new[]{(500d,"Right",false),(500d,"Right",true),(100d,"Right",true),(500d,"Bottom",true)}){var(width,label,open)=conf;var bar=new CommandBar{Width=width,IsOpen=open};var prop=typeof(CommandBar).GetProperty("DefaultLabelPosition")!;prop.SetValue(bar,Enum.Parse(prop.PropertyType,label));foreach(var (name,icon)in new[]{("Add",Symbol.Add),("Edit",Symbol.Edit),("Share",Symbol.Share)})bar.PrimaryCommands.Add(new AppBarButton{Label=name,Icon=new SymbolIcon(icon)});bar.SecondaryCommands.Add(new AppBarButton{Label="Settings",Icon=new SymbolIcon(Symbol.Setting)});await Record(theme,"CommandBar",$"{width}-{label}-{open}",bar,new{width,defaultLabelPosition=label,isOpen=open});bar.IsOpen=false;}
  }
  File.WriteAllText(Path.Combine(Program.Output,"command-controls-palettes.json"),JsonSerializer.Serialize(palettes,Options));File.WriteAllText(Path.Combine(Program.Output,"command-controls-metrics.json"),JsonSerializer.Serialize(new{dpi=root.XamlRoot.RasterizationScale,cases=rows,missing},Options));
 }
}
